package com.lexorion.payroll.config;import io.swagger.v3.oas.models.*;import io.swagger.v3.oas.models.info.Info;import io.swagger.v3.oas.models.security.*;import org.springframework.context.annotation.*;@Configuration public class OpenApiConfig{@Bean OpenAPI payrollOpenApi(){return new OpenAPI().info(new Info().title("Lexorion Payroll API").version("10F").description("Payroll Pay Run foundation. OWNER and ADMIN create workspace-scoped DRAFT Pay Runs, explicitly include employees, and read deterministic paginated history. Processing and finalization require payroll.processing and follow DRAFT to PROCESSING to CALCULATED to FINALIZED, with PROCESSING to FAILED on atomic calculation failure. Pay Runs reuse immutable Stage 10E calculation snapshots, enforce one currency, aggregate scale-4 totals, and remain immutable after finalization. calculationDate is explicit and may be inside or outside the pay period. Internal UUIDs are never public. No tax, payslip, payment, statutory, benefits, attendance, billing, or Finance behavior is implemented." )).components(new Components().addSecuritySchemes("bearer",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT"))).addSecurityItem(new SecurityRequirement().addList("bearer"));}}
